from datetime import date
from fastapi.responses import HTMLResponse


def dashboard_html(today: date) -> str:
    return '''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ANALISYS BETSTOTAL</title>
<style>
:root{--bg:#f3f6fb;--ink:#172033;--muted:#68758a;--line:#dfe5ee;--primary:#101827;--accent:#2563eb;--ok:#0f8a62;--danger:#a51d2d}
*{box-sizing:border-box}body{font-family:Inter,Segoe UI,Arial,sans-serif;background:var(--bg);margin:0;color:var(--ink)}
header{background:linear-gradient(135deg,#0b1220,#1c3157 65%,#2563eb);color:white;padding:26px 28px;box-shadow:0 4px 18px #17203322}header .head{max-width:1500px;margin:auto}h1{margin:0 0 5px;font-size:30px}header p{margin:0;color:#dbe7ff}.brand-badge{display:inline-block;margin-bottom:9px;padding:5px 10px;border-radius:999px;background:#ffffff18;border:1px solid #ffffff30;font-size:11px;font-weight:800;letter-spacing:.5px}
main{max-width:1500px;margin:22px auto;padding:0 18px}.main-nav{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:16px}.main-nav a,.main-nav button{border:1px solid var(--line);border-radius:11px;padding:10px 14px;text-decoration:none;background:white;color:var(--ink);cursor:pointer;font-weight:800;box-shadow:0 1px 5px #0000000b}.main-nav a.primary{background:var(--primary);color:white;border-color:var(--primary)}.main-nav a.live{background:#fff1f2;color:#a51d2d;border-color:#fecdd3}
.welcome{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,1fr);gap:16px;margin-bottom:18px}.welcome-card,.profile-card{background:white;border:1px solid var(--line);border-radius:16px;padding:20px;box-shadow:0 4px 16px #1720330c}.welcome-card{background:linear-gradient(135deg,#fff,#eef5ff)}.eyebrow{font-size:11px;font-weight:900;letter-spacing:.7px;color:var(--accent);text-transform:uppercase}.quote{font-size:21px;font-weight:800;line-height:1.35;margin:8px 0}.quote-meta{font-size:12px;color:var(--muted)}.profile-title{display:flex;justify-content:space-between;gap:12px;align-items:center}.profile-title h2{margin:0;font-size:17px}.profile-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px 14px;margin-top:12px}.profile-item{font-size:12px;color:var(--muted)}.profile-item b{display:block;color:var(--ink);font-size:14px;margin-top:2px;overflow:hidden;text-overflow:ellipsis}.profile-actions{margin-top:12px;display:flex;gap:8px;flex-wrap:wrap}.small-button{padding:8px 10px!important;font-size:12px}
.quick-title{font-size:12px;font-weight:900;color:#526079;margin:0 0 9px}.quick-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:20px}.quick{display:flex;align-items:center;justify-content:center;min-height:54px;text-align:center;border-radius:12px;background:white;border:1px solid var(--line);text-decoration:none;color:var(--ink);font-weight:900;box-shadow:0 2px 8px #0000000a}.quick:hover{transform:translateY(-1px);border-color:#b8c8e5}.quick.surebet{border-color:#bfdbfe;background:#eff6ff}.quick.telegram{border-color:#bae6fd;background:#f0f9ff}
.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}.tabs button{border:0;border-radius:10px;padding:10px 13px;background:white;cursor:pointer;font-weight:700;box-shadow:0 1px 5px #0001}.tabs .active{background:var(--ink);color:white}.card{background:white;border-radius:14px;padding:20px;box-shadow:0 2px 10px #0001;margin-bottom:18px;border:1px solid #e5eaf1}.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.metric b{font-size:25px;display:block;margin-top:6px}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #e7eaf0;text-align:left;font-size:13px}th{background:#f8f9fc}.muted{color:#697386}.notice{padding:12px;border-radius:10px;background:#fff8e6;margin-top:12px}.section-title{display:flex;justify-content:space-between;align-items:center;gap:10px}.strong{font-weight:800}.surebet-buttons{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}.live-button{background:#8b1e1e;color:white}.verify-button{padding:7px 9px;font-size:12px}.status{margin:8px 0;font-size:13px}.profit{font-weight:800}.home-footer{display:flex;justify-content:center;margin:26px 0 10px}.home-footer a{background:var(--primary);color:white;text-decoration:none;border-radius:11px;padding:11px 18px;font-weight:900}
.profile-edit{display:none;margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}.profile-edit.show{display:block}.profile-edit input{width:100%;border:1px solid #ccd6e5;border-radius:9px;padding:9px;margin:4px 0 8px;font:inherit}.profile-edit button{border:0;border-radius:9px;padding:9px 12px;background:var(--ink);color:white;font-weight:800;cursor:pointer}
@media(max-width:1050px){.quick-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.welcome{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,1fr)}table{display:block;overflow-x:auto;white-space:nowrap}}@media(max-width:600px){.quick-grid{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.profile-grid{grid-template-columns:1fr}h1{font-size:24px}}
</style></head><body>
<header><div class="head"><span class="brand-badge">PLATAFORMA DE ANÁLISIS DEPORTIVO</span><h1>⚽ ANALISYS BETSTOTAL</h1><p>Panel principal · Radar maestro · Surebet · Selección final · Backtest · CLV</p></div></header>
<main>
<nav class="main-nav" aria-label="Navegación principal"><a class="primary" href="/">🏠 PANEL PRINCIPAL</a><a class="live" href="#surebet-section">💰 SURBET</a><a href="/telegram-test">📨 TELEGRAM</a><a href="/provider-accounts">🔐 CONEXIÓN API</a><a href="/bookmakers">🏦 CASAS</a><a href="/panel">⚙️ CONFIGURACIÓN</a><a href="/docs">📚 API</a></nav>
<section class="welcome"><div class="welcome-card"><div class="eyebrow">Bienvenidos a ANALISYS BETSTOTAL</div><div id="dailyQuote" class="quote">Cargando frase inspiradora del día...</div><div id="quoteMeta" class="quote-meta">La frase se actualiza diariamente desde Internet.</div></div>
<div class="profile-card"><div class="profile-title"><h2>👤 Usuario</h2><span class="eyebrow">Perfil</span></div><div class="profile-grid"><div class="profile-item">USUARIO<b id="profileUser">LUCIANO</b></div><div class="profile-item">CORREO<b id="profileEmail">WSLUCIANO@HOTMAIL.COM</b></div><div class="profile-item">CLAVE<b>••••••••</b></div><div class="profile-item">ESTADO<b>🟢 ACTIVO</b></div></div><div class="profile-actions"><button class="small-button" onclick="toggleProfile()">✏️ CAMBIAR DATOS</button></div><div id="profileEdit" class="profile-edit"><label>Usuario</label><input id="editUser" value="LUCIANO"><label>Correo</label><input id="editEmail" value="WSLUCIANO@HOTMAIL.COM"><label>Nueva clave</label><input id="editPassword" type="password" placeholder="Dejar vacío para no cambiar"><button onclick="saveProfile()">GUARDAR PERFIL</button></div></div></section>
<div class="quick-title">ACCESOS RÁPIDOS</div><div class="quick-grid"><a class="quick surebet" href="#surebet-section">💰<br>SURBET</a><a class="quick" href="#master-section">🎯<br>RADAR MASTER</a><a class="quick" href="#final-section">🏆<br>SELECCIÓN FINAL</a><a class="quick" href="#backtest-section">🧪<br>BACKTEST</a><a class="quick telegram" href="/telegram-test">📨<br>TELEGRAM</a></div>
<div class="tabs"><button class="tab active" data-period="hoy">HOY</button><button class="tab" data-period="lunes-viernes">LUNES A VIERNES</button><button class="tab" data-period="sabado-domingo">SÁBADO A DOMINGO</button><button class="tab" data-period="mes">MES</button><button class="tab" data-period="3-meses">3 MESES</button><button class="tab" data-period="6-meses">6 MESES</button><button class="tab" data-period="todos">TODOS</button></div>
<div class="card" id="surebet-section"><div class="section-title"><h2>💰 Surebet</h2></div><div class="surebet-buttons"><button onclick="loadSurebetPre()">📅 SUREBET PRE-PARTIDO</button><button class="live-button" onclick="loadSurebetLive()">🔴 SUREBET EN VIVO · BUSCAR AHORA</button></div><div class="status muted" id="surebet-status">El modo EN VIVO no consulta la API hasta que pulses el botón.</div><div id="surebet" class="muted">Selecciona PRE-PARTIDO o EN VIVO.</div></div>
<div class="card" id="final-section"><div class="section-title"><h2>🎯 Selección final</h2><button onclick="loadFinal()">Actualizar</button></div><div id="final" class="muted">Cargando...</div></div>
<div class="card" id="master-section"><div class="section-title"><h2>🧠 Radar maestro</h2><button onclick="loadMaster()">Actualizar</button></div><div id="master" class="muted">Cargando...</div></div>
<div class="card"><h2>💰 Mis apuestas</h2><div id="performance" class="grid"></div></div>
<div class="card"><h2>📈 CLV</h2><div id="clv" class="grid"></div></div>
<div class="card" id="backtest-section"><div class="section-title"><h2>🧪 Backtest: original vs conservador vs real</h2><button onclick="loadBacktest()">Actualizar</button></div><div id="backtestResult" class="muted">Cargando...</div></div>
<div class="card"><h2>📊 Competición + mercado</h2><div id="groups" class="muted">Cargando...</div></div>
<div class="notice">⚠️ El sistema analiza datos y no garantiza ganancias. Una surebet se confirma solo después de verificar nuevamente las cuotas del evento. El radar EN VIVO es manual y no hace auto-refresh.</div>
<div class="home-footer"><a href="/">🏠 VOLVER AL PANEL PRINCIPAL</a></div>
</main><script>
let currentPeriod='hoy';
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function toggleProfile(){document.getElementById('profileEdit').classList.toggle('show')}
function saveProfile(){const u=document.getElementById('editUser').value.trim()||'LUCIANO',e=document.getElementById('editEmail').value.trim()||'WSLUCIANO@HOTMAIL.COM';document.getElementById('profileUser').textContent=u;document.getElementById('profileEmail').textContent=e;localStorage.setItem('analysisBetstotalProfile',JSON.stringify({user:u,email:e}));document.getElementById('profileEdit').classList.remove('show')}
function loadProfile(){try{const p=JSON.parse(localStorage.getItem('analysisBetstotalProfile')||'null');if(p?.user){document.getElementById('profileUser').textContent=p.user;document.getElementById('editUser').value=p.user}if(p?.email){document.getElementById('profileEmail').textContent=p.email;document.getElementById('editEmail').value=p.email}}catch(_){}}
async function loadDailyQuote(){const q=document.getElementById('dailyQuote'),m=document.getElementById('quoteMeta');try{const r=await fetch('https://zenquotes.io/api/today',{cache:'no-store'});if(!r.ok)throw new Error('quote');const d=await r.json();const x=Array.isArray(d)?d[0]:d;if(!x?.q)throw new Error('quote');q.textContent='“'+x.q+'”';m.textContent='— '+(x.a||'Autor desconocido')+' · Actualizada desde Internet hoy'}catch(_){q.textContent='“La disciplina de hoy construye los resultados de mañana.”';m.textContent='Frase de respaldo · se intentará actualizar desde Internet mañana'}}
document.querySelectorAll('.tab').forEach(x=>x.addEventListener('click',()=>{currentPeriod=x.dataset.period;document.querySelectorAll('.tab').forEach(y=>y.classList.toggle('active',y===x));loadPerformance();loadBacktest();loadCLV();}));
function renderSurebet(d){const rows=d.opportunities||[];if(!rows.length){document.getElementById('surebet').innerHTML='<p>No hay surebets disponibles con los datos actuales.</p>';return}document.getElementById('surebet').innerHTML='<table><thead><tr><th>Partido</th><th>Mercado</th><th>Línea</th><th>Resultado</th><th>Casa</th><th>Cuota</th><th>Margen</th><th>Acción</th></tr></thead><tbody>'+rows.flatMap(o=>Object.entries(o.outcomes||{}).map(([selection,q])=>`<tr><td>${esc(o.match)}</td><td>${esc(o.market)}</td><td>${esc(o.line??'-')}</td><td class="strong">${esc(selection)}</td><td>${esc(q.bookmaker)}</td><td>${q.odds}</td><td class="profit">${(o.profit_margin*100).toFixed(2)}%</td><td><button class="verify-button" onclick="verifySurebet(${o.match_id})">🔍 VERIFICAR</button></td></tr>`)).join('')+'</tbody></table>'}
async function loadSurebetPre(){document.getElementById('surebet-status').textContent='PRE-PARTIDO: usando únicamente las cuotas almacenadas; no se consulta OddsPapi.';const r=await fetch('/api/v1/arbitrage/pre-match?limit=100');const d=await r.json();document.getElementById('surebet-status').textContent=`📅 PRE-PARTIDO · ${d.opportunities?.length||0} surebets detectadas · sin consulta nueva.`;renderSurebet(d)}
async function loadSurebetLive(){document.getElementById('surebet-status').textContent='🔄 Consultando SOLO eventos EN VIVO ahora...';document.getElementById('surebet').innerHTML='<p>Buscando oportunidades live...</p>';try{const r=await fetch('/api/v1/arbitrage/live?limit=100&hours=1&limit_matches=20',{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Error al consultar live');document.getElementById('surebet-status').textContent=`🔴 EN VIVO actualizado ahora · ${d.sync.live_matches_seen||0} partidos live consultados · ${d.opportunities?.length||0} surebets. Pulsa VERIFICAR para confirmar una oportunidad.`;renderSurebet(d)}catch(e){document.getElementById('surebet-status').textContent='❌ No se pudo actualizar el radar live: '+e.message;document.getElementById('surebet').innerHTML=''}}
async function verifySurebet(matchId){document.getElementById('surebet-status').textContent='🔍 Verificando SOLO este partido y recalculando la surebet...';try{const r=await fetch(`/api/v1/arbitrage/verify/${matchId}?limit=100`,{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Error de verificación');document.getElementById('surebet-status').textContent=`${d.surebet_confirmed?'✅ SUREBET CONFIRMADA':'⚠️ SUREBET YA NO CONFIRMADA'} · Solo se actualizó este partido · ${d.odds_seen} cuotas recibidas.`;renderSurebet(d)}catch(e){document.getElementById('surebet-status').textContent='❌ Error verificando: '+e.message}}
async function loadFinal(){const d=await fetch('/api/v1/final-selection?limit=10').then(r=>r.json());const rows=d.opportunities||[];if(!rows.length){document.getElementById('final').innerHTML='<p>No hay apuestas que superen los filtros de seguridad actuales.</p>';return}document.getElementById('final').innerHTML='<table><thead><tr><th>Partido</th><th>Mercado</th><th>Selección</th><th>Cuota</th><th>Edge</th><th>EV</th><th>Score</th><th>Acción</th></tr></thead><tbody>'+rows.map(o=>`<tr><td>${esc(o.match)}</td><td>${esc(o.market)}</td><td class="strong">${esc(o.selection)}</td><td>${o.odds}</td><td>${(o.edge*100).toFixed(1)}%</td><td>${(o.ev*100).toFixed(1)}%</td><td>${o.master_score}</td><td class="strong">${esc(o.action)}</td></tr>`).join('')+'</tbody></table>'}
async function loadMaster(){const d=await fetch('/api/v1/master-radar?limit=15').then(r=>r.json());const rows=d.opportunities||[];if(!rows.length){document.getElementById('master').innerHTML='<p>No hay candidatos con datos suficientes.</p>';return}document.getElementById('master').innerHTML='<table><thead><tr><th>Partido</th><th>Mercado</th><th>Selección</th><th>Cuota</th><th>Edge</th><th>Consenso</th><th>Movimiento</th><th>CLV</th><th>Score</th><th>Rating</th></tr></thead><tbody>'+rows.map(o=>`<tr><td>${esc(o.match)}</td><td>${esc(o.market)}</td><td>${esc(o.selection)}</td><td>${o.odds}</td><td>${(o.edge*100).toFixed(1)}%</td><td>${o.bookmakers}</td><td>${(o.movement*100).toFixed(1)}%</td><td>${(o.average_clv*100).toFixed(2)}%</td><td class="strong">${o.master_score}</td><td>${esc((o.rating||'').toUpperCase())}</td></tr>`).join('')}</tbody></table>'}
async function loadPerformance(){const d=await fetch('/api/v1/bets/summary?period='+currentPeriod).then(r=>r.json());performance.innerHTML=`<div class="metric">Apuestas<b>${d.bets}</b></div><div class="metric">Ganadas<b>${d.wins}</b></div><div class="metric">Perdidas<b>${d.losses}</b></div><div class="metric">Neto<b>S/ ${d.net.toFixed(2)}</b></div><div class="metric">ROI<b>${(d.roi*100).toFixed(2)}%</b></div>`}
async function loadCLV(){const d=await fetch('/api/v1/clv/summary?period='+currentPeriod).then(r=>r.json());clv.innerHTML=`<div class="metric">Snapshots<b>${d.snapshots}</b></div><div class="metric">CLV positivo<b>${d.positive}</b></div><div class="metric">CLV negativo<b>${d.negative}</b></div><div class="metric">Tasa positiva<b>${(d.positive_rate*100).toFixed(1)}%</b></div><div class="metric">CLV medio<b>${(d.average_clv*100).toFixed(2)}%</b></div>`}
async function loadBacktest(){const d=await fetch('/api/v1/backtest/report?period='+currentPeriod).then(r=>r.json());const a=d.overall.original,c=d.overall.conservative,r=d.overall.actual;document.getElementById('backtestResult').innerHTML=`<table><thead><tr><th>Estrategia</th><th>Apuestas</th><th>Aciertos</th><th>Fallos</th><th>Hit rate</th><th>Net</th><th>ROI</th></tr></thead><tbody><tr><td>Original</td><td>${a.bets}</td><td>${a.wins}</td><td>${a.losses}</td><td>${(a.hit_rate*100).toFixed(1)}%</td><td>${a.net_units.toFixed(2)} u</td><td>${(a.roi*100).toFixed(2)}%</td></tr><tr><td>Conservador</td><td>${c.bets}</td><td>${c.wins}</td><td>${c.losses}</td><td>${(c.hit_rate*100).toFixed(1)}%</td><td>${c.net_units.toFixed(2)} u</td><td>${(c.roi*100).toFixed(2)}%</td></tr><tr><td>Real</td><td>${r.bets}</td><td>${r.wins}</td><td>${r.losses}</td><td>${(r.hit_rate*100).toFixed(1)}%</td><td>S/ ${r.net.toFixed(2)}</td><td>${(r.roi*100).toFixed(2)}%</td></tr></tbody></table>`}
async function loadGroups(){const d=await fetch('/api/v1/performance/competition-market').then(r=>r.json());if(!d.groups.length){groups.innerHTML='<p>Aún no hay resultados registrados.</p>';return}groups.innerHTML='<table><thead><tr><th>Competición</th><th>Mercado</th><th>Picks</th><th>Hit rate</th><th>ROI</th><th>Muestra</th></tr></thead><tbody>'+d.groups.map(x=>`<tr><td>${esc(x.competition)}</td><td>${esc(x.market)}</td><td>${x.picks}</td><td>${(x.hit_rate*100).toFixed(1)}%</td><td>${(x.roi*100).toFixed(2)}%</td><td>${esc(x.sample_status)}</td></tr>`).join('')}</tbody></table>'}
loadProfile();loadDailyQuote();loadFinal();loadMaster();loadPerformance();loadCLV();loadBacktest();loadGroups();</script></body></html>'''


def dashboard_response(today: date) -> HTMLResponse:
    return HTMLResponse(dashboard_html(today))
